const autoRefreshStaleAfter = 24 * time.Hour

func autoRefreshIfStale(ctx context.Context, flags *rootFlags, cmd *cobra.Command) error {
	resources := autoRefreshResources(cmd, flags)
	if len(resources) == 0 {
		return nil
	}

	dbPath := autoRefreshDBPath(cmd)
	db, err := store.OpenWithContext(ctx, dbPath)
	if err != nil {
		flags.freshnessMeta = map[string]any{
			"error":   fmt.Sprintf("opening local cache: %v", err),
			"db_path": dbPath,
		}
		return nil
	}
	defer db.Close()

	var liveClient interface {
		GetContext(context.Context, string, map[string]string) (json.RawMessage, error)
		RateLimit() float64
	}
	var clientErr error

	report, err := cliutil.EnsureFresh(ctx, cliutil.FreshnessOptions{
		Resources:  resources,
		StaleAfter: autoRefreshStaleAfter,
		State: func(_ context.Context, resource string) (cliutil.FreshnessState, error) {
			_, lastSynced, count, err := db.GetSyncState(resource)
			if err != nil {
				return cliutil.FreshnessState{}, err
			}
			return cliutil.FreshnessState{LastSynced: lastSynced, Count: count}, nil
		},
		Refresh: func(ctx context.Context, resource string) error {
			if liveClient == nil && clientErr == nil {
				liveClient, clientErr = flags.newClient()
			}
			if clientErr != nil {
				return clientErr
			}
			return refreshResourceHead(ctx, liveClient, db, resource)
		},
	})
	flags.freshnessMeta = report
	if err != nil {
		return err
	}
	return nil
}

func autoRefreshResources(cmd *cobra.Command, flags *rootFlags) []string {
	if cmd == nil || flags == nil || flags.dryRun || flags.noCache || flags.dataSource == "live" {
		return nil
	}
	if os.Getenv("DRIVETHRURPG_PP_AUTO_REFRESH") == "0" {
		return nil
	}

	switch cmd.Name() {
	case "sync", "doctor", "auth", "auth-key", "download", "agent-context", "which", "version", "completion", "profile", "feedback", "export", "import":
		return nil
	}

	if cmd.Name() == "analytics" {
		if resource := stringFlagValue(cmd, "type"); resource != "" {
			return knownSyncResources([]string{normalizeSyncResource(resource)})
		}
		return defaultSyncResources()
	}

	if cmd.Name() == "search" {
		if flags.dataSource != "local" {
			return nil
		}
		if resource := stringFlagValue(cmd, "type"); resource != "" {
			return knownSyncResources([]string{normalizeSyncResource(resource)})
		}
		return []string{"products", "library"}
	}

	if flags.dataSource != "local" {
		return nil
	}
	resource := resourceFromCommand(cmd)
	if resource == "" {
		return nil
	}
	return knownSyncResources([]string{resource})
}

func autoRefreshDBPath(cmd *cobra.Command) string {
	if cmd != nil {
		if flag := cmd.Flags().Lookup("db"); flag != nil && flag.Changed {
			if dbPath, err := cmd.Flags().GetString("db"); err == nil && dbPath != "" {
				return dbPath
			}
		}
	}
	return defaultDBPath("drivethrurpg-pp-cli")
}

func refreshResourceHead(ctx context.Context, c interface {
	GetContext(context.Context, string, map[string]string) (json.RawMessage, error)
	RateLimit() float64
}, db *store.Store, resource string) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	path, err := syncResourcePath(resource)
	if err != nil {
		return err
	}

	page := determinePaginationDefaults()
	data, err := c.GetContext(ctx, path, map[string]string{page.limitParam: strconv.Itoa(page.limit)})
	if err != nil {
		if warning, ok := isSyncAccessWarning(err); ok {
			return fmt.Errorf("refresh skipped: %s", warning.Reason)
		}
		return err
	}

	items, nextCursor, _ := extractPageItems(data, page.cursorParam)
	count := 1
	if len(items) == 0 {
		if err := upsertSingleObject(db, resource, data); err != nil {
			return err
		}
	} else {
		stored, _, err := upsertResourceBatch(db, resource, items)
		if err != nil {
			return err
		}
		count = stored
	}
	return db.SaveSyncState(resource, nextCursor, count)
}

func stringFlagValue(cmd *cobra.Command, name string) string {
	if cmd == nil || cmd.Flags().Lookup(name) == nil {
		return ""
	}
	value, err := cmd.Flags().GetString(name)
	if err != nil {
		return ""
	}
	return strings.TrimSpace(value)
}

func resourceFromCommand(cmd *cobra.Command) string {
	if cmd == nil {
		return ""
	}
	if endpoint := cmd.Annotations["pp:endpoint"]; endpoint != "" {
		resource := endpoint
		if i := strings.Index(resource, "."); i >= 0 {
			resource = resource[:i]
		}
		return normalizeSyncResource(resource)
	}
	if path := cmd.Annotations["pp:path"]; path != "" {
		path = strings.TrimPrefix(path, "/")
		if i := strings.Index(path, "/"); i >= 0 {
			path = path[:i]
		}
		return normalizeSyncResource(path)
	}
	return normalizeSyncResource(cmd.Name())
}

func normalizeSyncResource(resource string) string {
	resource = strings.TrimSpace(strings.ToLower(resource))
	resource = strings.ReplaceAll(resource, "_", "-")
	switch resource {
	case "order-products":
		return "library"
	default:
		return resource
	}
}

func knownSyncResources(resources []string) []string {
	seen := map[string]bool{}
	var known []string
	for _, resource := range resources {
		if resource == "" || seen[resource] {
			continue
		}
		if _, err := syncResourcePath(resource); err == nil {
			known = append(known, resource)
			seen[resource] = true
		}
	}
	return known
}
